const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const STORAGE_KEY = "cinema-watchlist-v1";
const PREF_KEY = "cinema-watchlist-prefs-v1";
let state = { watched: new Set(), query:"", view:"all", genre:"", sort:"custom", year:"", rating:"", selected:null, filterOpen:false };
const genres = [...new Set(MOVIES.flatMap(m => (m.genres||"").split(",").map(x=>x.trim()).filter(Boolean)))].sort();
const years = [...new Set(MOVIES.map(m=>String(m.year||"")).filter(y=>y && y!=="0"))].sort((a,b)=>Number(b)-Number(a));

function loadSaved(){
  try {
    const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}");
    state.watched=new Set(Array.isArray(raw.watched)?raw.watched:[]);
  } catch(e){ state.watched=new Set(); }
  try {
    const p=JSON.parse(localStorage.getItem(PREF_KEY)||"{}");
    if(p.view) state.view=p.view;
    if(p.sort) state.sort=p.sort;
  } catch(e){}
}
function saveWatched(){
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify({watched:[...state.watched], updatedAt:new Date().toISOString()})); }
  catch(e){ toast("Could not save on this browser. Try opening the hosted app in Safari."); }
  updateStats();
}
function savePrefs(){
  try { localStorage.setItem(PREF_KEY, JSON.stringify({view:state.view,sort:state.sort})); } catch(e){}
}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function rating(m){const n=Number(m.rating);return Number.isFinite(n)&&n>0?n.toFixed(1):"—";}
function isWatched(m){return state.watched.has(m.id);}
function genreMatches(m,g){return !g||(m.genres||"").split(",").map(x=>x.trim()).includes(g);}
function filteredMovies(){
  let arr=MOVIES.filter(m=>{
    if(state.view==="watchlist"&&isWatched(m))return false;
    if(state.view==="watched"&&!isWatched(m))return false;
    if(!genreMatches(m,state.genre))return false;
    if(state.year&&String(m.year)!==state.year)return false;
    if(state.rating&&(!Number(m.rating)||Number(m.rating)<Number(state.rating)))return false;
    const q=state.query.trim().toLowerCase();
    if(q&&!`${m.title} ${m.year} ${m.genres} ${m.director} ${m.synopsis}`.toLowerCase().includes(q))return false;
    return true;
  });
  if(state.sort==="title")arr.sort((a,b)=>a.title.localeCompare(b.title));
  else if(state.sort==="year")arr.sort((a,b)=>(Number(b.year)||0)-(Number(a.year)||0)||a.position-b.position);
  else if(state.sort==="rating")arr.sort((a,b)=>(Number(b.rating)||0)-(Number(a.rating)||0)||a.position-b.position);
  else if(state.sort==="unwatched")arr.sort((a,b)=>Number(isWatched(a))-Number(isWatched(b))||a.position-b.position);
  else arr.sort((a,b)=>a.position-b.position);
  return arr;
}
function card(m){
  const watched=isWatched(m);
  const first=(m.title||"?").split(/[\s:—-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase();
  return `<article class="movie-card ${watched?"is-watched":""}" data-id="${esc(m.id)}">
    <button class="poster poster-${Math.abs([...m.id].reduce((a,c)=>a+c.charCodeAt(0),0))%6}" data-action="detail" data-id="${esc(m.id)}" aria-label="Details for ${esc(m.title)}">
      <span class="poster-top">CINEMA CLUB <span>#${String(m.position).padStart(3,"0")}</span></span>
      <span class="poster-mark">${esc(first)}</span>
      <span class="poster-title">${esc(m.title)}</span>
      <span class="poster-year">${esc(m.year||"TBA")}</span>
    </button>
    <div class="card-info">
      <div class="card-heading"><button class="title-button" data-action="detail" data-id="${esc(m.id)}">${esc(m.title)}</button><span class="rating">★ ${rating(m)}</span></div>
      <p class="card-meta">${esc(m.year||"Year TBA")} · ${(m.genres||"").split(",").slice(0,2).map(esc).join(" · ")}</p>
      <div class="card-actions">
        <button class="watch-toggle ${watched?"checked":""}" data-action="toggle" data-id="${esc(m.id)}" aria-pressed="${watched}" aria-label="${watched?"Mark unwatched":"Mark watched"}">${watched?"✓ Watched":"+ Mark watched"}</button>
        <button class="more-button" data-action="detail" data-id="${esc(m.id)}" aria-label="More details">•••</button>
      </div>
    </div>
  </article>`;
}
function render(){
  const arr=filteredMovies();
  $("#movie-grid").innerHTML=arr.map(card).join("");
  $("#empty-state").hidden=arr.length!==0;
  $("#result-count").textContent=`${arr.length} ${arr.length===1?"movie":"movies"}`;
  $("#search-input").value=state.query;
  $("#genre-filter").value=state.genre;
  $("#year-filter").value=state.year;
  $("#rating-filter").value=state.rating;
  $("#sort-select").value=state.sort;
  $$(".tab").forEach(b=>{const active=b.dataset.view===state.view;b.classList.toggle("active",active);b.setAttribute("aria-selected",String(active));});
  $("#filter-badge").hidden=!(state.genre||state.year||state.rating);
  $("#filter-badge").textContent=[state.genre,state.year,state.rating?`${state.rating}+ ★`:""].filter(Boolean).length;
  updateStats();
}
function updateStats(){
  const n=state.watched.size,total=MOVIES.length;
  $("#stat-total").textContent=total;
  $("#stat-watched").textContent=n;
  $("#stat-left").textContent=total-n;
  $("#progress-label").textContent=`${Math.round(n/total*100)}% watched`;
  $("#progress-fill").style.width=`${n/total*100}%`;
}
function toggleWatched(id){
  if(state.watched.has(id))state.watched.delete(id);else state.watched.add(id);
  saveWatched(); render();
  if(state.selected===id)renderDetail(id);
  toast(state.watched.has(id)?"Added to Watched":"Moved back to Watchlist");
}
function openDetail(id){
  const m=MOVIES.find(x=>x.id===id);if(!m)return;
  state.selected=id;renderDetail(id);$("#detail-modal").showModal();
}
function renderDetail(id){
  const m=MOVIES.find(x=>x.id===id);if(!m)return;
  const watched=isWatched(m);
  $("#detail-content").innerHTML=`
    <div class="detail-hero poster-${Math.abs([...m.id].reduce((a,c)=>a+c.charCodeAt(0),0))%6}">
      <button class="detail-close" data-action="close-detail" aria-label="Close details">×</button>
      <span class="detail-eyebrow">CINEMA CLUB · #${String(m.position).padStart(3,"0")}</span>
      <div class="detail-title-wrap"><div class="detail-monogram">${esc((m.title||"?").split(/[\s:—-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase())}</div><h2>${esc(m.title)}</h2></div>
    </div>
    <div class="detail-body">
      <div class="detail-facts"><span>${esc(m.year||"Year TBA")}</span><span>★ ${rating(m)} IMDb</span>${m.runtime?`<span>${esc(m.runtime)} min</span>`:""}</div>
      <div class="genre-pills">${(m.genres||"Genre not listed").split(",").map(g=>`<span>${esc(g.trim())}</span>`).join("")}</div>
      <p class="detail-synopsis">${esc(m.synopsis||"No synopsis was included in the original list.")}</p>
      <dl class="detail-dl"><dt>Director</dt><dd>${esc(m.director||"Not listed")}</dd><dt>Release date</dt><dd>${esc(m.release||"Not listed")}</dd><dt>IMDb ID</dt><dd>${esc(m.id)}</dd></dl>
      <button class="primary-watch ${watched?"done":""}" data-action="toggle" data-id="${esc(m.id)}">${watched?"✓ Already watched · Mark unwatched":"＋ Mark as watched"}</button>
      <a class="imdb-link" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">View full details on IMDb ↗</a>
    </div>`;
}
function openFilters(){$("#filter-sheet").showModal();state.filterOpen=true;}
function closeFilters(){$("#filter-sheet").close();state.filterOpen=false;}
function toast(msg){
  const el=$("#toast");el.textContent=msg;el.classList.add("show");
  clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>el.classList.remove("show"),1900);
}
function fillOptions(){
  $("#genre-filter").innerHTML='<option value="">All genres</option>'+genres.map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join("");
  $("#year-filter").innerHTML='<option value="">Any year</option>'+years.map(y=>`<option value="${esc(y)}">${esc(y)}</option>`).join("");
}
function exportBackup(){
  const payload={format:"cinema-watchlist-backup-v1",watched:[...state.watched],exportedAt:new Date().toISOString()};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});
  const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="my-movie-watchlist-progress.json";a.click();URL.revokeObjectURL(a.href);
  toast("Progress backup exported");
}
function importBackup(file){
  if(!file)return;
  const reader=new FileReader();
  reader.onload=()=>{try{const obj=JSON.parse(reader.result);if(obj.format!=="cinema-watchlist-backup-v1"||!Array.isArray(obj.watched))throw Error("Invalid backup");state.watched=new Set(obj.watched.filter(id=>MOVIES.some(m=>m.id===id)));saveWatched();render();toast("Progress restored");}catch(e){toast("That backup file wasn't recognized");}};
  reader.readAsText(file);
}
function resetFilters(){
  state.genre="";state.year="";state.rating="";state.query="";
  $("#search-input").value="";render();closeFilters();
}
document.addEventListener("click",e=>{
  const el=e.target.closest("[data-action]");if(!el)return;
  const {action,id}=el.dataset;
  if(action==="toggle"){e.preventDefault();toggleWatched(id);}
  if(action==="detail")openDetail(id);
  if(action==="close-detail")$("#detail-modal").close();
  if(action==="open-filters")openFilters();
  if(action==="close-filters")closeFilters();
  if(action==="reset-filters")resetFilters();
  if(action==="export")exportBackup();
  if(action==="import")$("#import-file").click();
});
$("#search-input").addEventListener("input",e=>{state.query=e.target.value;render();});
$("#genre-filter").addEventListener("change",e=>{state.genre=e.target.value;render();});
$("#year-filter").addEventListener("change",e=>{state.year=e.target.value;render();});
$("#rating-filter").addEventListener("change",e=>{state.rating=e.target.value;render();});
$("#sort-select").addEventListener("change",e=>{state.sort=e.target.value;savePrefs();render();});
$$(".tab").forEach(b=>b.addEventListener("click",()=>{state.view=b.dataset.view;savePrefs();render();}));
$("#filter-form").addEventListener("change",()=>{state.genre=$("#genre-filter").value;state.year=$("#year-filter").value;state.rating=$("#rating-filter").value;render();});
$("#clear-search").addEventListener("click",()=>{state.query="";$("#search-input").value="";render();$("#search-input").focus();});
$("#export-progress").addEventListener("click",exportBackup);
$("#import-progress").addEventListener("click",()=>$("#import-file").click());
$("#import-file").addEventListener("change",e=>{importBackup(e.target.files[0]);e.target.value="";});
$("#detail-modal").addEventListener("click",e=>{if(e.target===$("#detail-modal"))$("#detail-modal").close();});
$("#filter-sheet").addEventListener("click",e=>{if(e.target===$("#filter-sheet"))closeFilters();});
loadSaved();fillOptions();render();
if("serviceWorker" in navigator && location.protocol!=="file:"){window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));}
